static TCFRAME liveFrame;static unsigned flushes;
static WORD task=1,lease,running,paused,done,ending,sentN,nframes,reads,physical;static DWORD ticks;static TCFRAME frames[1024],observed[2048];static unsigned recording,observedN;
HTASK GetCurrentTask(void){return task;}HMODULE GetModuleHandle(const char *n){return 33;}WORD GetModuleFileName(HMODULE m,char *p,WORD n){strcpy(p,"C:\\MMLAB\\MIDICLK.DLL");return strlen(p);}HMODULE LoadLibrary(const char *n){return 34;}WORD FreeLibrary(HMODULE m){return 0;}
static WORD openraw(void){if(lease)return 1;lease=1;sentN=nframes=running=done=ending=paused=0;ticks=0;return 0;}
static WORD putraw(TCFRAME *p){if(nframes==1024)return 2;frames[nframes++]=*p;if(recording&&observedN<2048)observed[observedN++]=*p;return 0;}static WORD startraw(void){running=1;return 0;}static WORD endraw(void){ending=1;return 0;}static WORD closeraw(void){lease=running=0;return 0;}static WORD debugraw(WORD q){reads++;if(q==2)return sentN;if(q==7)return done;if(q==12)return physical;return 0;}static DWORD clockraw(void){reads++;return ticks;}static WORD pauseraw(void){paused=1;return 0;}static WORD unpauseraw(void){paused=0;return 0;}static WORD flushraw(void){flushes++;sentN=nframes=running=ending=done=paused=0;ticks=0;return 0;}static WORD maskraw(void){return 0;}
static WORD applylive(TCFRAME *p){if(!lease)return 1;liveFrame=*p;sentN=1;nframes=done=ending=paused=0;ticks=0;physical++;return 0;}
void *GetProcAddress(HMODULE m,LPSTR p){switch((uintptr_t)p){case 13:return openraw;case 2:return putraw;case 3:case 17:return startraw;case 4:return endraw;case 5:return closeraw;case 6:return debugraw;case 11:return startraw;case 12:return clockraw;case 14:return pauseraw;case 15:return unpauseraw;case 16:return flushraw;case 18:return maskraw;case 19:return applylive;}return 0;}
static unsigned tests;static void ck(int ok,const char *name){tests++;if(!ok){fprintf(stderr,"FAIL %s test %u\n",name,tests);exit(1);}}
static void advance(DWORD ms){unsigned j;if(!paused)ticks+=MSCycles(ms);if(running&&!paused){for(j=0;j<nframes;j++)if((LONG)(ticks-frames[j].at)>=0){sentN++;physical++;}else break;if(j){memmove(frames,frames+j,(nframes-j)*sizeof(*frames));nframes-=j;}if(!nframes&&ending)done=1;}}
int main(void){WORD h,other;DWORD g,old,at;MDINFO st;unsigned i;ck(MDOpen(&h)==0,"open");MDStatus(h,&st,sizeof(st));g=st.generation;ck(st.size==40&&st.capacity==1024&&st.flags==0x100,"ABI");ck(MDOpen(&other)==MD_BUSY,"single owner");task=2;ck(MDReset(h,0)==MD_BUSY,"foreign reset");ck(MDClose(h)==MD_BUSY,"foreign close");ck(MDPush(h,g,55,0x7f3c90)==MD_BUSY,"foreign push");task=1;
 for(i=0;i<1024;i++)ck(MDPush(h,g,55,0x003c80)==0,"fill");ck(MDPush(h,g,55,0x003c80)==MD_FULL,"full");MDStatus(h,&st,sizeof(st));ck(st.accepted==1024,"full no accept");ck(MDReset(h,0)==0,"reset");MDStatus(h,&st,sizeof(st));ck(st.accepted==0&&st.generation!=g,"reset generation");ck(MDPush(h,g,55,0x7f3c90)==MD_STALE,"stale");g=st.generation;
 ck(MDPush(h,g,55,0x7f3c90)==0,"strict");ck(MDPush(h,g,56,0x003c80)==MD_SPACING,"spacing");ck(MDCommit(h,g,54,1)==MD_BAD,"bad commit atomic");ck(MDPush(h,g,70,0x003c80)==0,"after invalid commit");ck(MDCommit(h,g,200,1)==0&&MDStart(h)==0,"start");advance(80);MDPump(h);MDStatus(h,&st,sizeof(st));ck(st.delivered==2,"physical ack");ck(MDPause(h)==0,"pause");MDClock(h,&old);advance(400);MDClock(h,&at);ck(at==old,"pause freeze");ck(MDResume(h)==0,"resume");advance(200);MDPump(h);MDStatus(h,&st,sizeof(st));ck(st.state==MD_DONE,"done");
 ck(MDReset(h,0xffffff00u)==0,"wrap origin");MDStatus(h,&st,sizeof(st));g=st.generation;ck(MDPush(h,g,0xffffff37u,0x7f3c90)==0&&MDPush(h,g,0x1bcu,0x3c80)==0,"wrap push");ck(MDCommit(h,g,0x220,1)==0&&MDStart(h)==0,"wrap start");advance(400);MDClock(h,&at);ck(at>20&&at<500,"clock wrap");advance(450);MDPump(h);MDStatus(h,&st,sizeof(st));ck(st.state==MD_DONE&&st.delivered==2,"wrap done");
 ck(MDReset(h,0)==0,"reset dense");MDStatus(h,&st,sizeof(st));g=st.generation;ck(MDTiming(h,2)==0&&MDVoiceMode(h,0)==0,"late mode");for(i=0;i<100;i++)ck(MDPush(h,g,55+i,(i&1)?0x3c80:0x7f3c90)==0,"dense push");ck(MDCommit(h,g,200,1)==0&&MDStart(h)==0,"dense start");for(i=1;i<nframes;i++)ck(frames[i].at-frames[i-1].at>=MSCycles(8)-1,"physical spacing");advance(1400);MDPump(h);MDStatus(h,&st,sizeof(st));ck(st.state==MD_DONE&&st.delivered==100,"dense ack");ck(MDClose(h)==0&&!lease,"close");ck(MDOpen(&h)==0,"recovery open");MDStatus(h,&st,sizeof(st));g=st.generation;ck(MDTiming(h,2)==0&&MDVoiceMode(h,0)==0,"recovery mode");ck(MDPush(h,g,55,0x7f3c90)==0&&MDPush(h,g,75,0x3c80)==0,"recovery initial");ck(MDCommit(h,g,200,0)==0&&MDStart(h)==0,"recovery prime");advance(500);MDPump(h);ck(nframes==0,"recovery drained");old=reads;ck(MDPush(h,g,201,0x7f3c90)==0&&MDPush(h,g,202,0x3c80)==0&&MDPush(h,g,203,0x7f3c90)==0,"ordered late acceptance");ck(reads==old,"ordered admission has no hardware reads");MDClock(h,&at);ck(MDCommit(h,g,600,1)==0&&MDPump(h)==0,"recovery refill");ck(nframes&&frames[0].at>=MSCycles(at+250),"idle PIT recovery lead");advance(1500);MDPump(h);MDStatus(h,&st,sizeof(st));ck(st.state==MD_DONE&&st.accepted==5&&st.delivered==5,"recovery all acknowledged");ck(MDClose(h)==0,"recovery close");ck(MDOpen(&h)==0,"chunked open");MDStatus(h,&st,sizeof(st));g=st.generation;ck(MDVoiceMode(h,0)==0&&MDTiming(h,2)==0,"chunked flat ordered");recording=1;observedN=0;for(i=0;i<100;i++){ck(MDPush(h,g,55+20*i,(i&1)?0x3c80:0x7f3c90)==0,"chunk accept");if(i%10==9){ck(MDCommit(h,g,i==99?2100:55+20*(i+1)-1,i==99?1:0)==0,"chunk commit");if(i==9)ck(MDStart(h)==0,"chunk start");else ck(MDPump(h)==0,"chunk refill");advance(100);MDPump(h);}}advance(2500);MDPump(h);MDStatus(h,&st,sizeof(st));ck(st.state==MD_DONE&&st.delivered==100,"chunk complete");{unsigned j,index=0,last=15;for(j=0;j<observedN;j++){unsigned vol=observed[j].volume&15;if(vol!=last){if(!(index<100&&observed[j].at==MSCycles(55+20*index)))fprintf(stderr,"DEADLINE index=%u actual=%u expected=%u\n",index,(unsigned)observed[j].at,(unsigned)MSCycles(55+20*index));ck(index<100&&observed[j].at==MSCycles(55+20*index),"chunked event deadline equals preloaded deadline");index++;last=vol;}}ck(index==100,"chunk no duplicate or missing state");}recording=0;ck(MDClose(h)==0,"chunk close");printf("PASS actual MIDICLK source model checks=%u\n",tests);return 0;}
